<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import type { Client, ProposalDocument } from '../lib/types';
import { calculateInvestment, calculateMilestones, currencyPrecision, formatMoney } from '../lib/money';
const props=defineProps<{proposalId:string; initialDocument:ProposalDocument; clients:Client[]; initialClientId:string; status:string; activeShareUrl:string|null}>();
const document=ref<ProposalDocument>(structuredClone(props.initialDocument)); const clientId=ref(props.initialClientId); const activeSection=ref(document.value.sections[0]?.id??'details'); const saveState=ref<'saved'|'saving'|'unsaved'|'error'>('saved'); const notice=ref(''); let timer:number|undefined;
const active=computed(()=>document.value.sections.find(item=>item.id===activeSection.value)); const totals=computed(()=>calculateInvestment(document.value.phases,document.value.discountMinor,document.value.taxBasisPoints)); const milestoneAmounts=computed(()=>{try{return calculateMilestones(totals.value.totalMinor,document.value.milestones)}catch{return document.value.milestones.map(item=>({...item,amountMinor:0}))}}); const milestoneTotal=computed(()=>document.value.milestones.reduce((sum,item)=>sum+item.percentage,0));
const amountValue=(minor:number)=>minor/10**currencyPrecision(document.value.currency); const setAmount=(target:{amountMinor:number},event:Event)=>{target.amountMinor=Math.round(Number((event.target as HTMLInputElement).value||0)*10**currencyPrecision(document.value.currency))};
const save=async()=>{saveState.value='saving';const response=await fetch(`/api/admin/proposals/${props.proposalId}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({clientId:clientId.value,document:document.value})});saveState.value=response.ok?'saved':'error';if(!response.ok)notice.value=(await response.json()).error??'Save failed.'};
watch([document,clientId],()=>{saveState.value='unsaved';clearTimeout(timer);timer=globalThis.setTimeout(save,900)},{deep:true});
const guard=(event:BeforeUnloadEvent)=>{if(saveState.value==='unsaved'||saveState.value==='saving')event.preventDefault()};
onMounted(()=>window.addEventListener('beforeunload',guard));
onBeforeUnmount(()=>window.removeEventListener('beforeunload',guard));
const addPhase=()=>document.value.phases.push({id:crypto.randomUUID(),name:'New phase',description:'',amountMinor:0}); const addMilestone=()=>document.value.milestones.push({id:crypto.randomUUID(),percentage:0,description:'New milestone'});
const publish=async()=>{await save();if(saveState.value!=='saved')return;const response=await fetch(`/api/admin/proposals/${props.proposalId}/publish`,{method:'POST'});const data=await response.json();if(!response.ok){notice.value=data.error??'Unable to publish.';return}notice.value=`Published v${data.version}. Share link copied to clipboard.`;await navigator.clipboard?.writeText(data.url);};
const duplicate=async()=>{const response=await fetch(`/api/admin/proposals/${props.proposalId}/duplicate`,{method:'POST'});const data=await response.json();if(response.ok)location.href=`/proposals/${data.id}/edit`;};
const copyLink=async()=>{if(!props.activeShareUrl)return;await navigator.clipboard.writeText(props.activeShareUrl);notice.value='Active client link copied.'};
</script>
<template><div class="editor-shell"><aside class="editor-sections"><div class="editor-document-label"><small>Proposal structure</small><strong>{{document.proposalType==='quick'?'Quick quotation':'Full proposal'}}</strong></div><button class="section-tab" :class="{active:activeSection==='details'}" @click="activeSection='details'"><span>00</span>Proposal details</button><button v-for="(section,index) in document.sections" :key="section.id" class="section-tab" :class="{active:activeSection===section.id}" @click="activeSection=section.id"><span>{{String(index+1).padStart(2,'0')}}</span>{{section.title}}<i :class="{off:!section.enabled}"></i></button></aside><main class="editor-main"><div v-if="notice" class="alert" role="status">{{notice}} <button @click="notice=''">×</button></div><section v-if="activeSection==='details'" class="editor-card"><header><p class="eyebrow">Foundation</p><h2>Proposal details</h2><p>The essential information used throughout the proposal.</p></header><div class="form-grid"><label class="form-field wide"><span>Proposal title</span><input v-model="document.title"/></label><label class="form-field wide"><span>Project name</span><input v-model="document.projectName"/></label><label class="form-field"><span>Client</span><select v-model="clientId"><option v-for="client in clients" :value="client.id">{{client.company||client.name}}</option></select></label><label class="form-field"><span>Proposal number</span><input v-model="document.proposalNumber"/></label><label class="form-field"><span>Issue date</span><input v-model="document.issueDate" type="date"/></label><label class="form-field"><span>Expiration date</span><input v-model="document.expirationDate" type="date"/></label><label class="form-field"><span>Currency</span><select v-model="document.currency"><option>USD</option><option>IDR</option></select></label></div></section><section v-else-if="active?.kind==='investment'" class="editor-card"><header><p class="eyebrow">Commercials</p><h2>Investment</h2><p>Price by project phase and deliverable—never by arbitrary page counts.</p></header><div class="segmented"><label><input v-model="document.pricingDisplay" type="radio" value="total"/>Show total only</label><label><input v-model="document.pricingDisplay" type="radio" value="phases"/>Show phase breakdown</label></div><div class="repeater"><article v-for="(phase,index) in document.phases" :key="phase.id" class="repeater-row"><span class="drag-handle">{{String(index+1).padStart(2,'0')}}</span><div><input v-model="phase.name" aria-label="Phase name"/><input v-model="phase.description" aria-label="Phase description" placeholder="Scope or deliverables"/></div><div class="money-input"><span>{{document.currency}}</span><input :value="amountValue(phase.amountMinor)" type="number" min="0" :step="document.currency==='USD'?0.01:1" @input="setAmount(phase,$event)"/></div><button class="icon-button" @click="document.phases.splice(index,1)">×</button></article></div><button class="button button-secondary" @click="addPhase">＋ Add phase</button><div class="totals-box"><div><span>Subtotal</span><strong>{{formatMoney(totals.subtotalMinor,document.currency)}}</strong></div><label><span>Discount</span><input :value="amountValue(document.discountMinor)" type="number" min="0" @input="document.discountMinor=Math.round(Number(($event.target as HTMLInputElement).value)*10**currencyPrecision(document.currency))"/></label><label><span>Tax (%)</span><input :value="document.taxBasisPoints/100" type="number" min="0" max="100" step="0.01" @input="document.taxBasisPoints=Math.round(Number(($event.target as HTMLInputElement).value)*100)"/></label><div class="total-line"><span>Total investment</span><strong>{{formatMoney(totals.totalMinor,document.currency)}}</strong></div></div></section><section v-else-if="active?.kind==='payment'" class="editor-card"><header><p class="eyebrow">Commercials</p><h2>Payment schedule</h2><p>Amounts recalculate automatically and the final milestone absorbs any rounding remainder.</p></header><div class="repeater"><article v-for="(milestone,index) in document.milestones" :key="milestone.id" class="repeater-row milestone"><span class="drag-handle">{{String(index+1).padStart(2,'0')}}</span><input v-model="milestone.description" aria-label="Milestone description"/><div class="percent-input"><input v-model.number="milestone.percentage" type="number" min="1" max="100"/><span>%</span></div><strong>{{formatMoney(milestoneAmounts[index]?.amountMinor||0,document.currency)}}</strong><button class="icon-button" @click="document.milestones.splice(index,1)">×</button></article></div><button class="button button-secondary" @click="addMilestone">＋ Add milestone</button><p class="validation-line" :class="{invalid:milestoneTotal!==100}">{{milestoneTotal}}% allocated <span>{{milestoneTotal===100?'✓ Ready':'Must equal 100%'}}</span></p></section><section v-else-if="active" class="editor-card"><header><p class="eyebrow">Content section</p><div class="section-title-row"><h2>{{active.title}}</h2><label class="toggle"><input v-model="active.enabled" type="checkbox"/><span></span>{{active.enabled?'Visible':'Hidden'}}</label></div><p>Use clear, restrained formatting. Line breaks become readable proposal paragraphs or list items.</p></header><label class="form-field"><span>Section title</span><input v-model="active.title"/></label><label class="form-field"><span>Content</span><textarea v-model="active.content" rows="14"></textarea></label></section></main><aside class="editor-inspector"><div class="inspector-preview"><p class="eyebrow">Live summary</p><span class="mini-kicker">Proposal for</span><h3>{{clients.find(c=>c.id===clientId)?.company||clients.find(c=>c.id===clientId)?.name}}</h3><p>{{document.projectName}}</p><div class="mini-total"><span>Total investment</span><strong>{{formatMoney(totals.totalMinor,document.currency)}}</strong></div></div><div class="inspector-actions"><span class="save-state" :class="saveState"><i></i>{{saveState}}</span><button class="button button-secondary button-full" @click="save">Save now</button><a class="button button-secondary button-full" :href="`/proposals/${proposalId}/preview`" target="_blank">Preview ↗</a><button v-if="activeShareUrl" class="button button-secondary button-full" @click="copyLink">Copy active link</button><button class="button button-dark button-full" :disabled="milestoneTotal!==100" @click="publish">Publish proposal</button><button class="text-button" @click="duplicate">Duplicate proposal</button></div><small class="version-note" v-if="status!=='draft'">Edits are saved as a draft revision. The shared version changes only when republished.</small></aside></div></template>
